"""Audit conclusions from independently checked data and saved diagnostics."""
from pathlib import Path
import json
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path(__file__).resolve().parents[1];out=root/'artifacts/audit_v3';figs=root/'figures/audit_v3';figs.mkdir(exist_ok=True,parents=True)
data=json.loads((out/'data_audit.json').read_text());diag=json.loads((out/'lstm_diagnostics.json').read_text());training=json.loads((out/'training_diagnostics.json').read_text())
old=json.loads((root/'artifacts/validation_v2/comparison.json').read_text());traj=json.loads((root/'artifacts/evaluation.json').read_text())
summary=[]
for label,name in [('LSTM original, 30 épocas','LSTM_head')]:
 rows=[r for r in old if r['experiment']=='all' and r['method']==name and r['class']=='ALL']
 summary.append({'method':label,'accuracy':float(np.mean([r['accuracy'] for r in rows])),'aw_mae':float(np.mean([r['aw_mae'] for r in rows])),'aw_mae_seed_sd':float(np.std([r['aw_mae'] for r in rows],ddof=1)),'body_rmse_mm':float(np.mean([r['body_rmse_m'] for r in traj if r['experiment']=='all' and r['method']=='LSTM' and r['class']=='ALL']))*1000})
for mode,label in [('joint_120','LSTM conjunta, até 120 épocas'),('rms_only_120','LSTM somente RMS, até 120 épocas')]:
 rows=[r for r in diag if r['mode']==mode]
 summary.append({'method':label,'accuracy':float(np.mean([r['accuracy'] for r in rows])),'aw_mae':float(np.mean([r['aw_mae'] for r in rows])),'aw_mae_seed_sd':float(np.std([r['aw_mae'] for r in rows],ddof=1)),'body_rmse_mm':float(np.mean([r['body_rmse_m'] for r in rows]))*1000 if mode=='joint_120' else None})
for key,label in [('all_eight','Ridge, oito características'),('past_RMS_persistence','Persistência do RMS passado')]:
 r=data['ablations_fixed_alpha'][key];summary.append({'method':label,'accuracy':r['accuracy'],'aw_mae':r['aw_mae'],'aw_mae_seed_sd':0,'body_rmse_mm':None})
(out/'summary.json').write_text(json.dumps(summary,indent=2))
macros={'AuditJointAcc':f"{summary[1]['accuracy']*100:.1f}",'AuditJointMAE':f"{summary[1]['aw_mae']:.3f}",'AuditJointBody':f"{summary[1]['body_rmse_mm']:.3f}",'AuditOnlyAcc':f"{summary[2]['accuracy']*100:.1f}",'AuditOnlyMAE':f"{summary[2]['aw_mae']:.3f}",'AuditPastMAE':f"{summary[-1]['aw_mae']:.3f}"}
(root/'paper/results_v3.tex').write_text('% Generated from artifacts/audit_v3/summary.json\n'+'\n'.join('\\newcommand{\\'+k+'}{'+v.replace('.',',')+'}' for k,v in macros.items())+'\n')
lines=['# Auditoria de validade: resultados e correções','','## Conclusão','','Os 100% foram reproduzidos por cálculo independente, mas não representam resolução geral do problema. A classificação deste recorte é pouco exigente: manter o RMS passado também acerta todos os rótulos. A comparação anterior subestimou a LSTM ao encerrar em 30 épocas sem demonstrar estabilização.','','| Método | Acerto (%) | MAE do RMS (m/s²) | RMSE carroceria (mm) |','|---|---:|---:|---:|']
for r in summary:lines.append(f"| {r['method']} | {r['accuracy']*100:.2f} | {r['aw_mae']:.4f} | "+('—' if r['body_rmse_mm'] is None else f"{r['body_rmse_mm']:.4f}")+' |')
lines+=['','LSTM: média de três sementes. O diagnóstico somente RMS não produz trajetórias treinadas. ARX original: RMSE de carroceria 0,4885 mm. A média da LSTM conjunta longa fica próxima e varia entre sementes; isso não demonstra superioridade estatística.','','## Verificações independentes','','- RMS recalculado com FFT explícita/ponderação polinomial: diferença máxima de aproximadamente 8,8e-9 m/s² frente aos valores salvos, compatível com float32/float64.','- Regressão refeita com mínimos quadrados ampliados/SVD: diferença máxima de aproximadamente 1,1e-9 m/s² nas previsões. Acurácia independente: 100%.','- Não houve sobreposição das fases completas de histórico e alvo entre treino e validação, nas verificações implementadas. Registros de teste são outra realização; normalizadores conferem com o treino.','- A classe ISO e a aceleração futura não entram nas características da Ridge. A entrada de pista futura é uma hipótese explícita compartilhada com a LSTM.','- Não se identificou erro numérico ou vazamento direto do alvo nas verificações efetuadas; isso não equivale a provar ausência de toda forma de dependência entre os dados.','','## Por que o teste permite 100%','','- Dentro de cada realização, A–E são a mesma forma de onda multiplicada por amplitude. O resíduo relativo de proporcionalidade foi da ordem de 1e-16. As cinco classes não representam cinco formas independentes de excitação.','- A/B e C–E ficam em lados separados do limiar de 0,315. A avaliação é predominantemente de níveis estacionários de intensidade, não de transições entre conforto e desconforto na mesma pista.','- A persistência do RMS dos cinco segundos anteriores alcança 100% e MAE 0,0448 m/s². Não usa dados futuros nem aprende parâmetros.','- Usar somente características históricas ou somente da pista futura também reproduz 100% neste recorte, embora com maior erro contínuo que as oito características.','- Em 100 permutações agrupadas dos alvos de treino, a acurácia variou de 45,6% a 90,0%, com mediana 60%. É um controle diagnóstico, não um p-valor: janelas vizinhas se sobrepõem.','- O 100% não persiste em todo limiar: com limiares 0,5 e 1,0, por exemplo, a Ridge apresentou aproximadamente 92,2% e 89,6%. Não se escolheu outro limiar para melhorar o resultado.','','## Por que a comparação anterior desfavorecia a LSTM','','- Cinco das seis melhores validações originais ocorreram na última época disponível, 30. O orçamento não demonstrava convergência.','- A Ridge recebe resumos de intensidade e diferenças já calculadas, e otimiza somente log-RMS. A LSTM original recebe sequências e otimiza três trajetórias mais o indicador. Isso não isola o efeito da arquitetura.','- A atualização de parâmetros no T4 foi conferida antes/depois da troca CPU/GPU usada nos checkpoints. Na versão efetiva, as identidades se preservaram e o otimizador continuou atualizando os pesos. Não se encontrou esse defeito.','- O diagnóstico longo usa a mesma arquitetura com até 120 épocas e paciência 15, seleção somente na validação, em três sementes. Os 100% reaparecem na LSTM conjunta.','- A cabeça direta continua sem consistência física imposta com a trajetória de aceleração. Retirar a perda das trajetórias não trouxe melhora uniforme; todas as sementes foram preservadas.','','## Limites da conclusão','','Esta auditoria é exploratória, pois o teste já foi consultado. Não cria um novo teste cego, novas formas de pista ou validação de conforto humano. Os rótulos continuam sensíveis ao filtro e não há acelerometria independente. É prematuro afirmar que a LSTM seja inferior por natureza; também não há evidência de que a complexidade seja necessária para classificar esse alvo.','']
(root/'docs/RESULTADOS_AUDITORIA_V3.md').write_text('\n'.join(lines))
plt.rcParams.update({'font.size':10})
fig,axs=plt.subplots(1,2,figsize=(11,4));labels=['LSTM 30','LSTM conjunta 120','LSTM RMS 120','Ridge 8','RMS passado']
axs[0].bar(labels,[r['accuracy']*100 for r in summary]);axs[0].set(ylabel='Acerto do indicador (%)',ylim=(0,105));axs[0].tick_params(axis='x',rotation=25)
axs[1].bar(labels,[r['aw_mae'] for r in summary],yerr=[r['aw_mae_seed_sd'] for r in summary],capsize=3);axs[1].set(ylabel='MAE do RMS (m/s²)');axs[1].tick_params(axis='x',rotation=25)
fig.tight_layout();fig.savefig(figs/'audit_summary.png',dpi=180);plt.close(fig)
fig,axs=plt.subplots(1,2,figsize=(10,4))
for ax,mode in zip(axs,['joint_120','rms_only_120']):
 for r in training:
  if r['mode']!=mode:continue
  ax.plot([v['epoch'] for v in r['log']],[v['validation_criterion'] for v in r['log']],label=str(r['seed']))
 ax.axvline(30,color='gray',ls='--',label='limite anterior');ax.set(xlabel='Época',ylabel='Critério de validação',title=mode);ax.legend(fontsize=8)
fig.tight_layout();fig.savefig(figs/'lstm_training_budget.png',dpi=180);plt.close(fig)
print(json.dumps(summary,indent=2))
